2	// Paths and shapes follow the 2026-10-01 service contract (sections 3-6).
3	// Test-customer answers come verbatim from test-customers.json via data.js (see build_data.py).
4	// Stateless: statement.week.change and statement.pdf.send do not change anything.
5	
6	import { CUSTOMERS, CARDS } from "./data.js";
7	
8	const BASE = "/voice/v1/";
9	const SERVICES = [
10	  "cards.list",
11	  "cards.balance",
12	  "statement.week.get",
13	  "statement.week.decide",
14	  "statement.week.change",
15	  "contact.email.get",
16	  "statement.pdf.send",
17	];
