20	const TEMPLATE_CUSTOMER = "90000001";
21	const TEMPLATE_CARD = "540000******1234";
22	
23	const CORS = { "Access-Control-Allow-Origin": "*" };
24	
25	function json(body, status = 200) {
26	  return Response.json(body, { status, headers: CORS });
27	}
28	
29	function guid() {
30	  return crypto.randomUUID().replace(/-/g, "");
31	}
32	
33	function errorBody(code, message, type, rootCause) {
34	  const g = guid();
35	  return {
36	    result: {
37	      guid: g,
38	      returnCode: code,
39	      messageText: message,
40	      code: code,
41	      message: message,
42	      type: type,
43	      details: { guid: g, rootCause: rootCause, errorOrigin: "ivr-gateway-test:ivr-channel-v0" },
44	    },
45	  };
46	}
47	
48	const NOT_FOUND = "com.freyabank.ivrgateway.ivrchannel.rest.exception.NotFoundException";
49	
50	function invalidArgs(message) {
51	  return json(errorBody("INVALID_ARGUMENTS_ERROR", message, "ERROR", "InvalidArgumentsException"), 400);
52	}
53	
54	// Contract section 4: the 404 of each service (400 where the service has no 404).
55	const NOT_FOUND_ERRORS = {
