59	    json(errorBody("FB_IVR_CHANNEL_120", "Kart bakiye servisi hatası: kart bulunamadı", "WARNING", NOT_FOUND), 404),
60	  "statement.week.get": () =>
61	    json(errorBody("FB_IVR_CHANNEL_121", "Hesap kesim haftası servisi hatası: kart bulunamadı", "WARNING", NOT_FOUND), 404),
62	  "statement.pdf.send": () => json(errorBody("FB_IVR_CHANNEL_107", "Pdf dokümanı bulunamadı", "WARNING", NOT_FOUND), 404),
63	  "statement.week.decide": () => invalidArgs("no statement week preview for this card and week"),
64	  "statement.week.change": () => invalidArgs("no statement week change for this card and week"),
65	  "contact.email.get": () => invalidArgs("customer not found"),
66	};
67	
68	function isTemplate(v) {
69	  return typeof v === "string" && (v.trim().startsWith("{{") || v.trim().startsWith("%7B%7B"));
70	}
71	
72	function isEmpty(v) {
73	  return v === undefined || v === null || (typeof v === "string" && v.trim() === "");
74	}
75	
76	function norm(v) {
77	  return String(v).trim();
78	}
79	
80	async function serve(entry) {
81	  if (entry.delaySeconds) await new Promise((r) => setTimeout(r, entry.delaySeconds * 1000));
82	  // entry.body is the test file's response, pre-serialized (keeps 0.0 etc. exactly as listed).
83	  return new Response(entry.body, {
84	    status: entry.http,
85	    headers: { ...CORS, "Content-Type": "application/json; charset=utf-8" },
86	  });
87	}
